  if (view_type != "main" && view_type != "popup" && view_type != "devtools") {
    isolate->ThrowException(v8::Exception::TypeError(
        v8::String::NewFromUtf8(isolate, "Invalid view type").ToLocalChecked()));
    return;
  }

  std::vector<content::WebContents*> extension_views;
  // Assume GetExtensionViewsByWindowId() is a helper function that retrieves all WebContents
  // related to the given browser window ID and view type, filtering out iframes.
  extension_views = GetExtensionViewsByWindowId(browser_window_id, view_type);

  v8::Local<v8::Array> result = v8::Array::New(isolate, extension_views.size());

  for (size_t i = 0; i < extension_views.size(); ++i) {
    result->Set(context, i, v8::External::New(isolate, extension_views[i])).Check();
  }

  args.GetReturnValue().Set(result);
}

